draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw bacteria
  ctx.fillStyle = 'black';
  ctx.lineWidth = 3;
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W / 2 + Math.sin(t + i) * 50, H / 2 + Math.cos(t + i) * 50, 10, 0, 2 * Math.PI);
    ctx.stroke();
  }

  // draw fiber
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2);
  ctx.lineTo(W / 2 + Math.sin(t) * 100, H / 2 + Math.cos(t) * 100);
  ctx.stroke();

  // draw feeding
  ctx.fillStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W / 2 + Math.sin(t) * 100, H / 2 + Math.cos(t) * 100, 5, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
